// Turn the app's payload into Pinecone's NDJSON upsert format.
//
// Integrated inference means we send text, not vectors — Pinecone embeds on arrival.
// The text field name must match the index's field_map, which on this index is `text`.
//
// llama-text-embed-v2 caps input at 2048 tokens. The app chunks to ~800, so this is
// headroom rather than a real limit, but a record over the cap is dropped here with a
// reason rather than failing the whole batch.

const body = $input.first().json.body ?? $input.first().json;
const { documentId, projectId, userId, namespace, chunks } = body;

if (!namespace || !Array.isArray(chunks)) {
  throw new Error('payload must include namespace and chunks[]');
}

const MAX_CHARS = 2048 * 4; // ~4 chars per token

const accepted = [];
const rejected = [];

for (const c of chunks) {
  if (!c.id || typeof c.content !== 'string' || !c.content.trim()) {
    rejected.push({ chunkId: c.id ?? 'unknown', error: 'empty content' });
    continue;
  }
  if (c.content.length > MAX_CHARS) {
    rejected.push({ chunkId: c.id, error: 'exceeds model input limit' });
    continue;
  }
  accepted.push({
    _id: c.id,
    text: c.content,
    document_id: documentId,
    project_id: projectId,
    user_id: userId,
    chunk_index: c.index,
  });
}

if (accepted.length === 0) {
  return [{ json: { namespace, ndjson: '', accepted: [], rejected, skip: true } }];
}

return [{
  json: {
    namespace,
    ndjson: accepted.map((r) => JSON.stringify(r)).join('\n'),
    accepted: accepted.map((r) => r._id),
    rejected,
    skip: false,
  },
}];
